  // 9B. INVOICE DELETE ACTION HANDLER
  async deleteInvoice(invoiceId) {
    const inv = (this.db?.invoices || []).find(i => i.id === invoiceId || i.invoice_no === invoiceId);
    const label = inv ? inv.invoice_no : invoiceId;
    const invId = inv ? inv.id : invoiceId;
    const invNo = inv ? inv.invoice_no : invoiceId;
    if (!confirm(`Are you sure you want to delete Tax Invoice ${label}?`)) return;

    try {
      await this.syncApi('delete_invoice', { invoice_id: invId, invoice_no: invNo, id: invId });
    } catch (err) {
      console.warn('API sync warning for delete_invoice:', err);
    }

    const getSeqNum = (str) => {
      if (!str) return null;
      const m = String(str).match(/(?:REC-(?:INVOICE|INV|RG|RG-INV)-?|)(1\d{3}|44\d{3}[A-Z]?)(?:_|$|[^0-9A-Z])/i);
      return m ? m[1].toUpperCase() : null;
    };
    const delSeq = getSeqNum(invNo) || getSeqNum(invId) || getSeqNum(invoiceId);

    if (this.db.invoices) {
      this.db.invoices = this.db.invoices.filter(i => {
        if (i.id === invId || i.id === invoiceId) return false;
        if (i.invoice_no === invNo || i.invoice_no === invoiceId) return false;
        if (invNo && (i.invoice_no || '').toLowerCase() === invNo.toLowerCase()) return false;
        if (delSeq) {
          const itemSeq = getSeqNum(i.invoice_no) || getSeqNum(i.id);
          if (itemSeq && itemSeq === delSeq) return false;
        }
        return true;
      });
    }

    // Also remove any allocations in customer receipts pointing to this invoice
    if (this.db.customer_receipts) {
      this.db.customer_receipts.forEach(rcp => {
        if (rcp.allocations && Array.isArray(rcp.allocations)) {
          rcp.allocations = rcp.allocations.filter(a => a.invoice_id !== invoiceId && a.invoice_no !== invoiceId && a.invoice_no !== label);
        }
      });
    }

    this.normalizeAllBalances();
    try {
      localStorage.setItem('rayan_fin_db_cache', JSON.stringify(this.db));
    } catch (e) {}

    this.showNotification(`Tax Invoice ${label} deleted successfully.`, 'info');
    this.renderActiveTab();
  }

  // 9C. CUSTOMER DELETE ACTION HANDLER
  async deleteCustomer(customerId) {
    const cust = (this.db?.customers || []).find(c => c.id === customerId || c.code === customerId || c.name === customerId);
    const label = cust ? (cust.name || cust.code) : customerId;
    const custId = cust ? cust.id : customerId;
    const custCode = cust ? (cust.code || '') : '';
    const custName = cust ? (cust.name || '') : '';

    if (!confirm(`Are you sure you want to delete customer/client "${label}"? This action cannot be undone.`)) return;

    try {
      await this.syncApi('delete_customer', { customer_id: custId, code: custCode, name: custName, id: custId });
    } catch (err) {
      console.warn('API sync warning for delete_customer:', err);
    }

    if (this.db.customers) {
      this.db.customers = this.db.customers.filter(c => 
        c.id !== custId && 
        c.id !== customerId && 
        (custCode ? c.code !== custCode : true) && 
        (custName ? (c.name || '').toLowerCase() !== custName.toLowerCase() : true)
      );
    }

    try {
      localStorage.setItem('rayan_fin_db_cache', JSON.stringify(this.db));
    } catch (e) {}

    this.closeModal('modal-edit-cust');
    this.closeModal('modal-cust-profile');
    this.showNotification(`Customer "${label}" deleted successfully.`, 'info');
    this.renderActiveTab();
  }

